import React from 'react';
import { motion } from 'framer-motion';
import { ArrowRight, Play, TrendingUp, Users, Globe } from 'lucide-react';
import { Button } from '../ui/button';

const stats = [
  { icon: TrendingUp, value: '500+', label: 'Projects Delivered' },
  { icon: Users, value: '200+', label: 'Happy Clients' },
  { icon: Globe, value: '15+', label: 'Countries Served' },
];

export const Hero = () => {
  return (
    <section id="home" className="relative min-h-[90vh] overflow-hidden">
      {/* Background */}
      <div className="absolute inset-0 bg-hero" />

      {/* Background Image Overlay */}
      <div
        className="absolute inset-0 opacity-20"
        style={{
          backgroundImage: 'url(https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1920&q=80)',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
        }}
      />

      {/* Gradient Overlay */}
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-primary/50 to-primary/90" />

      {/* Content */}
      <div className="relative container mx-auto px-6 lg:px-8 pt-24 pb-12 min-h-[90vh] flex flex-col justify-center">
        <div className="max-w-3xl">
          {/* Main Headline */}
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="heading-display text-3xl sm:text-4xl lg:text-5xl text-primary-foreground mb-4"
          >
            From Vision to{' '}
            <span className="text-gradient-gold">Venture Success</span>
          </motion.h1>

          {/* Subheadline */}
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="text-body text-base md:text-lg text-primary-foreground/80 max-w-xl mb-8 leading-relaxed"
          >
            We partner with ambitious entrepreneurs and established businesses to transform ideas into thriving enterprises. Strategic consulting, expert training, and global trading solutions.
          </motion.p>

          {/* CTAs */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="flex flex-col sm:flex-row gap-3 mb-10"
          >
            <Button variant="gold" size="lg" className="group">
              Schedule Consultation
              <ArrowRight className="ml-2 w-4 h-4 group-hover:translate-x-1 transition-transform" />
            </Button>
            <Button variant="hero" size="lg" className="group">
              <Play className="mr-2 w-4 h-4" />
              Watch Our Story
            </Button>
          </motion.div>

          {/* Stats - Inline */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
            className="flex flex-wrap gap-8"
          >
            {stats.map((stat) => (
              <div key={stat.label} className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-secondary/20 flex items-center justify-center">
                  <stat.icon className="w-5 h-5 text-secondary" />
                </div>
                <div>
                  <div className="text-xl font-bold text-primary-foreground">{stat.value}</div>
                  <div className="text-xs text-primary-foreground/60">{stat.label}</div>
                </div>
              </div>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
};
